# ---------------------------------------------------------------------------
# Fast path A1: divisible downsampling / equal size with whole-row tiles
#   Di % Do == 0, Hi % Ho == 0, Wi % Wo == 0, and BW == Wo so a program covers
#   whole grad_output rows. Then grad_input[i,j,k] = grad_output[i//rD, j//rH,
#   k//rW] / (rD*rH*rW), and for one od the rH row copies and rW W-copies of RT
#   consecutive grad_output rows form ONE contiguous grad_input span of
#   RT*rH*Wi elements, so each of the rD planes is written with a single flat
#   unit-stride store after one register broadcast of the loaded tile.
#   PROG_D consecutive od planes are handled per program to keep the grid inside
#   one wave when the total program count would otherwise exceed the core count.
# ---------------------------------------------------------------------------
@triton.jit
def _down_full_kernel(
    gout_ptr,
    out_ptr,
    Do,
    Ho,
    Wo,
    Hi,
    Wi,
    rD,
    DOB,  # DOB = Do // PROG_D : od blocks per (n,c) plane
    planeNC,  # Do*Ho*Wo : grad_output (n,c) plane stride
    planeHW,  # Ho*Wo    : grad_output od plane stride
    spatial_in,  # Di*Hi*Wi : grad_input (n,c) plane stride
    divf,  # rD*rH*rW : output window extent product (float)
    RT: tl.constexpr,
    RH: tl.constexpr,
    BW: tl.constexpr,
    RW: tl.constexpr,
    PROG_D: tl.constexpr,
):
    pid1 = tl.program_id(1)
    pid2 = tl.program_id(2)  # nc*DOB + od block

    odb = pid2 % DOB
    nc = pid2 // DOB

    oh = pid1 * RT + tl.arange(0, RT)
    ow = tl.arange(0, BW)
    oh_ok = oh < Ho

    ih0 = pid1 * (RT * RH)
    ROWLEN: tl.constexpr = BW * RW  # == Wi
    TOT: tl.constexpr = RT * RH * ROWLEN
    # the span is contiguous, so the valid part is a single prefix
    cnt = tl.minimum(Hi - ih0, RT * RH) * ROWLEN
    t = tl.arange(0, TOT)
    mask = t < cnt

    for pd in tl.static_range(PROG_D):
        od = odb * PROG_D + pd
        off = nc * planeNC + od * planeHW + oh[:, None] * Wo + ow[None, :]
        v = tl.load(gout_ptr + off, mask=oh_ok[:, None], other=0.0)
        y = (v.to(tl.float32) / divf).to(out_ptr.dtype.element_ty)
        val = tl.reshape(
            tl.broadcast_to(y[:, None, :, None], (RT, RH, BW, RW)),
            (TOT,),
        )
        base = nc * spatial_in + (od * rD) * (Hi * Wi) + ih0 * Wi
        for kd in range(0, rD):
            tl.store(out_ptr + base + kd * (Hi * Wi) + t, val, mask=mask)


# ---------------------------------------------------------------------------
# Fast path A2: divisible downsampling / equal size, partial-row tiles
# (Wo not a power of two, or wider than the W tile).
# ---------------------------------------------------------------------------
@triton.jit
def _down_kernel(
    gout_ptr,
    out_ptr,
    Do,
    Ho,
    Wo,
    Hi,
    Wi,
    rD,
    rH,
    planeNC,
    planeHW,
    spatial_in,
    divf,
    RT: tl.constexpr,
    BW: tl.constexpr,
    RW: tl.constexpr,
):
    pid0 = tl.program_id(0)
    pid1 = tl.program_id(1)
    pid2 = tl.program_id(2)  # nc*Do + od

    od = pid2 % Do
    nc = pid2 // Do

    oh = pid1 * RT + tl.arange(0, RT)
    ow = pid0 * BW + tl.arange(0, BW)
    idx = tl.arange(0, BW * RW)

    off = nc * planeNC + od * planeHW + oh[:, None] * Wo + ow[None, :]
    v = tl.load(gout_ptr + off, mask=(oh < Ho)[:, None] & (ow < Wo)[None, :], other=0.0)
    y = (v.to(tl.float32) / divf).to(out_ptr.dtype.element_ty)
    val = tl.reshape(tl.broadcast_to(y[:, :, None], (RT, BW, RW)), (RT, BW * RW))

    # grad_input linear position of (iw, j) inside the tile is pid0*(BW*RW) + idx
    wmask = (pid0 * (BW * RW) + idx) < Wi
    rm = (oh < Ho)[:, None] & wmask[None, :]
    HiWi = Hi * Wi
    ih = oh * rH
    base = nc * spatial_in + (od * rD) * HiWi + pid0 * (BW * RW)
    for kd in range(0, rD):
        for kh in range(0, rH):
            ob = base + kd * HiWi + (ih + kh)[:, None] * Wi + idx[None, :]
            tl.store(out_ptr + ob, val, mask=rm)


# ---------------------------------------------------------------------------
# Fast path B: divisible upsampling
#   Do % Di == 0, Ho % Hi == 0, Wo % Wi == 0  (rD, rH, rW = Do/Di, Ho/Hi, Wo/Wi)
# Then every output window extent is exactly 1, so the result is a pure
# rD x rH x rW box sum of grad_output.
# ---------------------------------------------------------------------------
@triton.jit
def _box_sum_kernel(
    gout_ptr,
    out_ptr,
    Di,
    Hi,
    Wi,
    Ho,
    Wo,
    rD,
    rH,
    planeNC,  # Do*Ho*Wo : stride between consecutive (n,c) planes of grad_output
    planeHW,  # Ho*Wo    : stride between consecutive od planes
    RT: tl.constexpr,
    BW: tl.constexpr,
    RW: tl.constexpr,
):
    pid0 = tl.program_id(0)
    pid1 = tl.program_id(1)
    pid2 = tl.program_id(2)  # nc*Di + id

    id_ = pid2 % Di
    nc = pid2 // Di

    ih = pid1 * RT + tl.arange(0, RT)
    iw = pid0 * BW + tl.arange(0, BW)
    ow = pid0 * (BW * RW) + tl.arange(0, BW * RW)

    ih_ok = ih < Hi
    ow_ok = ow < Wo

    base = nc * planeNC + (id_ * rD) * planeHW + (pid1 * (RT * rH)) * Wo

    row_off = tl.arange(0, RT)[:, None] * (rH * Wo) + ow[None, :]
    m = ih_ok[:, None] & ow_ok[None, :]

    acc = tl.zeros([RT, BW], dtype=tl.float32)
    for kd in range(0, rD):
        for kh in range(0, rH):
            off = base + kd * planeHW + kh * Wo + row_off
            v = tl.load(gout_ptr + off, mask=m, other=0.0)
            acc += tl.sum(tl.reshape(v.to(tl.float32), (RT, BW, RW)), axis=2)

    # pid2 already encodes the Di factor, so the output plane stride is Hi*Wi.
    ooff = pid2 * (Hi * Wi) + ih[:, None] * Wi + iw[None, :]
    tl.store(
        out_ptr + ooff,
        acc.to(out_ptr.dtype.element_ty),
        mask=ih_ok[:, None] & (iw < Wi)[None, :],
    )


# ---------------------------------------------------------------------------
# General path: arbitrary adaptive window sizes (non-divisible ratios). One lane
# per input cell, runtime-bounded masked loops.
# ---------------------------------------------------------------------------
@triton.jit
def _aap3d_bwd_kernel(
    gout_ptr,
    out_ptr,
    Di,
    Hi,
    Wi,
    Do,
    Ho,
    Wo,
    sN,
    sC,
    sD,
    sH,
    sW,
    maxd,
    maxh,
    maxw,
    spatial,
    BLOCK: tl.constexpr,
):
    pid0 = tl.program_id(0)
    c = tl.program_id(1)
    n = tl.program_id(2)

    sp = pid0 * BLOCK + tl.arange(0, BLOCK)
    valid = sp < spatial

    iw = sp % Wi
    t = sp // Wi
    ih = t % Hi
    id_ = t // Hi

    # Output window bounds (inclusive start, exclusive end) for this input cell.
    od0 = (id_ * Do) // Di
    od1 = ((id_ + 1) * Do + (Di - 1)) // Di
    oh0 = (ih * Ho) // Hi
    oh1 = ((ih + 1) * Ho + (Hi - 1)) // Hi
    ow0 = (iw * Wo) // Wi
    ow1 = ((iw + 1) * Wo + (Wi - 1)) // Wi

    base = n * sN + c * sC
    acc = tl.zeros([BLOCK], dtype=tl.float32)

    for kd in range(0, maxd):
        od = od0 + kd
        mD = od < od1
        odc = tl.minimum(od, Do - 1)
        # window extent of output position odc, measured in input space
        kD = ((((odc + 1) * Di + (Do - 1)) // Do) - ((odc * Di) // Do)).to(tl.float32)
        po = base + odc * sD
        for kh in range(0, maxh):
            oh = oh0 + kh
            mH = mD & (oh < oh1)
            ohc = tl.minimum(oh, Ho - 1)
            kH = ((((ohc + 1) * Hi + (Ho - 1)) // Ho) - ((ohc * Hi) // Ho)).to(
                tl.float32
            )
            pq = po + ohc * sH
            for kw in range(0, maxw):
                ow = ow0 + kw
                m = valid & mH & (ow < ow1)
                owc = tl.minimum(ow, Wo - 1)
                kW = ((((owc + 1) * Wi + (Wo - 1)) // Wo) - ((owc * Wi) // Wo)).to(
                    tl.float32
                )
                v = tl.load(gout_ptr + pq + owc * sW, mask=m, other=0.0)
                acc += v.to(tl.float32) / (kD * kH * kW)

    out_off = (n * tl.num_programs(1) + c) * spatial + sp
    tl.store(out_ptr + out_off, acc.to(out_ptr.dtype.element_ty), mask=valid)


def _max_count(inp, out):
    """Exact maximum number of output positions containing one input cell, per dim."""
    if inp <= 0 or out <= 0:
        return 0
    g = math.gcd(inp, out)
    p = out // g
    q = inp // g
    return (p + 2 * q - 2) // q


def _tile_rows(bw, rw):
    """Rows per program: keep a program's flat span near 512 elements."""
    rt = 1
    while rt < 8 and rt * 2 * (bw * rw) <= 1024:
        rt *= 2
    return rt


_MAX_GRID = 65535
_INT32_MAX = 2**31 - 1
_AIV_BLOCKS = 40  # wave size used only to decide od-plane grouping


def run(*args, **kwargs):
    a = list(args)
    grad_output = kwargs.get("grad_output", a.pop(0) if a else None)
    inp = kwargs.get("self", kwargs.get("input", a.pop(0) if a else None))
    if grad_output is None or inp is None:
        raise TypeError("run(grad_output, self) requires both tensors")

    ishape = inp.shape
    oshape = grad_output.shape
    Di, Hi, Wi = ishape[-3], ishape[-2], ishape[-1]
    Do, Ho, Wo = oshape[-3], oshape[-2], oshape[-1]

    out = torch.empty(ishape, dtype=inp.dtype, device=inp.device)

    spatial = Di * Hi * Wi
    if spatial == 0:
        return out
    NC = inp.numel() // spatial
    if NC == 0:
        return out

    divisible = (
        Do > 0
        and Ho > 0
        and Wo > 0
        and grad_output.dim() == inp.dim()
        and grad_output.is_contiguous()
        and grad_output.numel() == NC * Do * Ho * Wo
        and grad_output.numel() <= _INT32_MAX
    )

    # ---- fast path A: divisible downsampling / equal size -------------------
    if divisible and Di % Do == 0 and Hi % Ho == 0 and Wi % Wo == 0:
        rD = Di // Do
        rH = Hi // Ho
        rW = Wi // Wo
        if rW in (1, 2, 4, 8) and NC * Do <= _MAX_GRID:
            bw = 1
            while bw < Wo and bw < 64:
                bw *= 2
            # one flat store per od plane: grow RT until the store burst reaches
            # ~4-8 KB (RT*rH*BW*RW elements), bounded by Ho.
            rt = 1
            while rt * 2 <= 32 and (rt * 2) * rH * bw * rW <= 8192 and rt * 2 <= Ho:
                rt *= 2
            if bw == Wo and rt * rH * bw * rW <= 8192:
                # whole rows: one flat contiguous store per od plane
                rows = triton.cdiv(Ho, rt)
                prog_d = 1
                if Do % 2 == 0 and _AIV_BLOCKS < rows * NC * Do <= 2 * _AIV_BLOCKS:
                    prog_d = 2
                grid = (1, rows, NC * (Do // prog_d))
                _down_full_kernel[grid](
                    grad_output,
                    out,
                    Do,
                    Ho,
                    Wo,
                    Hi,
                    Wi,
                    rD,
                    Do // prog_d,
                    Do * Ho * Wo,
                    Ho * Wo,
                    spatial,
                    float(rD * rH * rW),
                    RT=rt,
                    RH=rH,
                    BW=bw,
                    RW=rW,
                    PROG_D=prog_d,
                )
            else:
                grid = (triton.cdiv(Wo, bw), triton.cdiv(Ho, rt), NC * Do)
                _down_kernel[grid](
                    grad_output,
                    out,
                    Do,
                    Ho,
                    Wo,
                    Hi,
                    Wi,
                    rD,
                    rH,
                    Do * Ho * Wo,
                    Ho * Wo,
                    spatial,
                    float(rD * rH * rW),
                    RT=rt,
                    BW=bw,
                    RW=rW,
                )
            return out

    # ---- fast path B: divisible upsampling ---------------------------------
    if divisible and Do % Di == 0 and Ho % Hi == 0 and Wo % Wi == 0:
        rD = Do // Di
        rH = Ho // Hi
        rW = Wo // Wi
        if rW in (1, 2, 4, 8) and NC * Di <= _MAX_GRID:
            bw = 1
            while bw < Wi and bw < 64:
                bw *= 2
            rt = _tile_rows(bw, rW)
            while rt > 1 and rt > Hi:
                rt //= 2
            grid = (triton.cdiv(Wi, bw), triton.cdiv(Hi, rt), NC * Di)
            _box_sum_kernel[grid](
                grad_output,
                out,
                Di,
                Hi,
                Wi,
                Ho,
                Wo,
                rD,
                rH,
                Do * Ho * Wo,
                Ho * Wo,
                RT=rt,
                BW=bw,
                RW=rW,
            )
            return out

    # ---- general path ------------------------------------------------------
    st = grad_output.stride()
    if inp.dim() == 5:
        N, C = ishape[0], ishape[1]
        sN, sC, sD, sH, sW = st[0], st[1], st[2], st[3], st[4]
    else:
        N, C = 1, ishape[0]
        sN, sC, sD, sH, sW = 0, st[0], st[1], st[2], st[3]

    if N == 0 or C == 0 or N > _MAX_GRID or C > _MAX_GRID:
        return out

    maxd = _max_count(Di, Do)
    maxh = _max_count(Hi, Ho)
    maxw = _max_count(Wi, Wo)

    total = N * C * spatial
    if total <= 2048:
        BLOCK = 64
    elif total <= 32768:
        BLOCK = 256
    else:
        BLOCK = 1024

    grid = (triton.cdiv(spatial, BLOCK), C, N)
    _aap3d_bwd_kernel[grid](
        grad_output,
        out,
        Di,
        Hi,
        Wi,
        Do,
        Ho,
        Wo,
        sN,
        sC,
        sD,
        sH,
        sW,
        maxd,
        maxh,
        maxw,
        spatial,
        BLOCK=BLOCK,
    )
    return out


